defense.secure_config:
# Enforce MFA + IP restriction on IAM user:
# IAM policy condition:
# {
#   'Condition': {
#     'Bool': {'aws:MultiFactorAuthPresent': 'true'},
#     'IpAddress': {'aws:SourceIp': ['10.0.0.0/8', '203.0.113.0/24']}
#   }
# }

# AWS Config rule: no long-term access keys for root:
aws configservice put-config-rule --config-rule file://no-root-access-key.json

# Prefer IAM roles over access keys:
# For EC2: attach IAM role → credentials via IMDS (auto-rotated)
# For humans: AWS SSO with SAML → temporary credentials only

# Alert on credential report: keys older than 90 days:
aws iam generate-credential-report
aws iam get-credential-report | base64 -d | grep AKIA | awk -F, '$10>90{print $1,$10}'
